mapper.sql:
(SELECT MAX(lq.quote_id) FROM quotes lq
WHERE lq.project_id = ${projectColumn}
AND lq.deleted_at IS NULL)

mapper.update:
UPDATE quotes
SET deadline_date = #{deadlineDate}
WHERE quote_id = #{quoteId}
AND quote_status = '未判定'
AND deleted_at IS NULL

mapper.delete:
DELETE FROM quotes
WHERE quote_id = #{id}
AND deleted_at IS NOT NULL

mapper.update:
UPDATE quotes
SET quote_status = #{quoteStatus},
judge_user = #{judgeUser}
WHERE quote_id = #{quoteId}

mapper.select:
SELECT * FROM quote_histories
WHERE quote_id = #{id}
ORDER BY updated_at DESC

SELECT h.*, (q.deleted_at IS NOT NULL) AS quote_deleted FROM quote_histories h JOIN quotes q ON h.quote_id = q.quote_id WHERE q.project_id = #{projectId}
AND q.deleted_at IS NULL
ORDER BY h.updated_at DESC
